mapper.select:
select ti.album_id, ai.album_title, ti.id track_id, ti.track_title, ti.cover_url, ti.media_duration, ti.status, max(if(ts.stat_type = '0401',ts.stat_num,0)) playStatNum, max(if(ts.stat_type = '0402',ts.stat_num,0)) subscribeStatNum, max(if(ts.stat_type = '0403',ts.stat_num,0)) buyStatNum, max(if(ts.stat_type = '0404',ts.stat_num,0)) commentStatNum from track_info ti left join track_stat ts on ti.id = ts.track_id left join album_info ai on ai.id = ti.album_id
ti.is_deleted = 0 and ai.is_deleted = 0 and ts.is_deleted = 0
and ti.user_id = #{trackInfoQuery.userId}
and ti.status = #{trackInfoQuery.status}
and ti.track_title = cancat('%',#{trackInfoQuery.trackTitle},'%')
group by ti.id order by ti.id desc
